#include <bits/stdc++.h>
using namespace std;

using LL = long long;
using P = pair<int, int>;
const LL MOD = 1000000009;

LL mod_pow(LL base, LL exp, LL m = MOD) {
    LL res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % m;
        base = (base * base) % m;
        exp >>= 1;
    }
    return res;
}

struct ModNumber {
    LL val;
    ModNumber() : val(0) {}
    ModNumber(LL v) {
        val = v % MOD;
        if (val < 0) val += MOD;
    }
    operator int() const { return (int)val; }
    ModNumber& operator+=(const ModNumber& other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }
    ModNumber& operator-=(const ModNumber& other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }
    ModNumber& operator*=(const ModNumber& other) {
        val = (val * other.val) % MOD;
        return *this;
    }
    friend ModNumber operator+(ModNumber a, const ModNumber& b) { return a += b; }
    friend ModNumber operator-(ModNumber a, const ModNumber& b) { return a -= b; }
    friend ModNumber operator*(ModNumber a, const ModNumber& b) { return a *= b; }
    friend ModNumber operator^(ModNumber a, LL n) {
        ModNumber res(1);
        while (n > 0) {
            if (n & 1) res *= a;
            a *= a;
            n >>= 1;
        }
        return res;
    }
};

LL inv(LL a, LL p) {
    if (a == 1) return 1;
    return (1 - p * inv(p % a, a)) / a + p;
}

const int MAXN = 262144;
ModNumber factorial[MAXN], inv_factorial[MAXN];

void init_factorials() {
    factorial[0] = ModNumber(1);
    for (int i = 1; i < MAXN; i++) {
        factorial[i] = factorial[i - 1] * ModNumber(i);
    }
    inv_factorial[MAXN - 1] = ModNumber(1) / factorial[MAXN - 1];
    for (int i = MAXN - 2; i >= 0; i--) {
        inv_factorial[i] = inv_factorial[i + 1] * ModNumber(i + 1);
    }
}

ModNumber comb(int a, int b) {
    if (a < 0 || b < 0 || a < b) return ModNumber(0);
    return factorial[a] * inv_factorial[b] * inv_factorial[a - b];
}

pair<ModNumber, ModNumber> multiply_pairs(pair<ModNumber, ModNumber> a, pair<ModNumber, ModNumber> b) {
    return {a.first * b.first, a.second * b.first + a.first * b.second};
}

pair<ModNumber, ModNumber> add_pairs(pair<ModNumber, ModNumber> a, pair<ModNumber, ModNumber> b) {
    return {a.first + b.first, a.second + b.second};
}

pair<ModNumber, ModNumber> dp[501];
bool used[501];

void setup_dp() {
    init_factorials();
    dp[0] = {ModNumber(1), ModNumber(0)};
    dp[1] = {ModNumber(2), ModNumber(0)};
    for (int n = 2; n <= 500; n++) {
        for (int j = 0; j < n; j++) {
            ModNumber cnt = ModNumber(n + 1);
            ModNumber sum = ModNumber(0);
            for (int k = 0; k < n; k++) {
                sum += abs(j - k);
            }
            auto left = dp[j];
            auto right = dp[n - 1 - j];
            auto x = multiply_pairs(left, right);
            x.first *= comb(n - 1, j);
            x.second *= comb(n - 1, j);
            x.first *= cnt;
            x.second *= cnt + sum;
            dp[n] = add_pairs(dp[n], x);
        }
    }
}

pair<ModNumber, ModNumber> dp2[502][501];

void process_input() {
    int n, m; cin >> n >> m;
    setup_dp();
    for (int i = 0; i <= n; i++) {
        for (int k = 0; k <= m; k++) {
            dp2[i][k] = {ModNumber(0), ModNumber(0)};
        }
    }
    dp2[0][0] = {ModNumber(1), ModNumber(0)};
    for (int i = 0; i < n; i++) {
        for (int k = 0; k <= m; k++) {
            if (dp2[i][k].first.val == 0 && dp2[i][k].second.val == 0) continue;
            for (int j = i; j < n; j++) {
                int ni = j + 2;
                if (ni > n) ni = n;
                int nk = k + j - i + 1;
                if (nk <= m) {
                    auto x = multiply_pairs(dp2[i][k], dp[j - i + 1]);
                    x.first *= comb(nk, k);
                    x.second *= comb(nk, k);
                    dp2[ni][nk] = add_pairs(dp2[ni][nk], x);
                }
            }
            if (i + 1 <= n && k <= m) {
                dp2[i + 1][k] = add_pairs(dp2[i + 1][k], dp2[i][k]);
            }
        }
    }
    cout << (int)dp2[n][m].second << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    process_input();
    return 0;
}
