import java.util.Scanner;

public class Main {
    static final long MOD = 1000000009L;
    static final int MAXN = 262144;
    static ModNumber[] factorial = new ModNumber[MAXN];
    static ModNumber[] invFactorial = new ModNumber[MAXN];

    static class Pair {
        ModNumber first;
        ModNumber second;

        Pair(ModNumber f, ModNumber s) {
            this.first = f;
            this.second = s;
        }
    }

    static class ModNumber {
        long val;

        ModNumber() {
            this.val = 0;
        }

        ModNumber(long v) {
            this.val = v % MOD;
            if (this.val < 0) this.val += MOD;
        }

        ModNumber add(ModNumber other) {
            long res = this.val + other.val;
            if (res >= MOD) res -= MOD;
            return new ModNumber(res);
        }

        ModNumber subtract(ModNumber other) {
            long res = this.val - other.val;
            if (res < 0) res += MOD;
            return new ModNumber(res);
        }

        ModNumber multiply(ModNumber other) {
            long res = (this.val * other.val) % MOD;
            return new ModNumber(res);
        }

        ModNumber pow(long n) {
            ModNumber res = new ModNumber(1);
            ModNumber base = new ModNumber(this.val);
            while (n > 0) {
                if ((n & 1) == 1) res = res.multiply(base);
                base = base.multiply(base);
                n >>= 1;
            }
            return res;
        }

        static ModNumber inv(long a) {
            if (a == 1) return new ModNumber(1);
            return new ModNumber((1 - MOD * inv(MOD % a, a)) / a + MOD);
        }

        static ModNumber inv(ModNumber a) {
            return inv(a.val);
        }

        static ModNumber divide(ModNumber a, ModNumber b) {
            return a.multiply(inv(b));
        }
    }

    static void initFactorials() {
        factorial[0] = new ModNumber(1);
        for (int i = 1; i < MAXN; i++) {
            factorial[i] = factorial[i - 1].multiply(new ModNumber(i));
        }
        invFactorial[MAXN - 1] = ModNumber.inv(factorial[MAXN - 1]);
        for (int i = MAXN - 2; i >= 0; i--) {
            invFactorial[i] = invFactorial[i + 1].multiply(new ModNumber(i + 1));
        }
    }

    static ModNumber comb(int a, int b) {
        if (a < 0 || b < 0 || a < b) return new ModNumber(0);
        return factorial[a].multiply(invFactorial[b]).multiply(invFactorial[a - b]);
    }

    static Pair multiplyPairs(Pair a, Pair b) {
        return new Pair(a.first.multiply(b.first), a.second.multiply(b.first).add(a.first.multiply(b.second)));
    }

    static Pair addPairs(Pair a, Pair b) {
        return new Pair(a.first.add(b.first), a.second.add(b.second));
    }

    static Pair[] dp = new Pair[501];
    static boolean[] used = new boolean[501];

    static Pair[][] dp2 = new Pair[502][501];

    static void setupDP() {
        initFactorials();
        for (int i = 0; i <= 500; i++) {
            dp[i] = new Pair(new ModNumber(0), new ModNumber(0));
        }
        dp[0] = new Pair(new ModNumber(1), new ModNumber(0));
        dp[1] = new Pair(new ModNumber(2), new ModNumber(0));
        for (int n = 2; n <= 500; n++) {
            for (int j = 0; j < n; j++) {
                ModNumber cnt = new ModNumber(n + 1);
                ModNumber sum = new ModNumber(0);
                for (int k = 0; k < n; k++) {
                    sum = sum.add(new ModNumber(Math.abs(j - k)));
                }
                Pair left = dp[j];
                Pair right = dp[n - 1 - j];
                Pair x = multiplyPairs(left, right);
                x.first = x.first.multiply(comb(n - 1, j));
                x.second = x.second.multiply(comb(n - 1, j)).add(x.first.multiply(sum));
                dp[n] = addPairs(dp[n], x);
            }
        }
    }

    static void processInput() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        setupDP();

        for (int i = 0; i <= n; i++) {
            for (int k = 0; k <= m; k++) {
                dp2[i][k] = new Pair(new ModNumber(0), new ModNumber(0));
            }
        }
        dp2[0][0] = new Pair(new ModNumber(1), new ModNumber(0));

        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= m; k++) {
                if (dp2[i][k].first.val == 0 && dp2[i][k].second.val == 0) continue;
                for (int j = i; j < n; j++) {
                    int ni = j + 2;
                    if (ni > n) ni = n;
                    int nk = k + j - i + 1;
                    if (nk <= m) {
                        Pair x = multiplyPairs(dp2[i][k], dp[j - i + 1]);
                        x.first = x.first.multiply(comb(nk, k));
                        x.second = x.second.multiply(comb(nk, k));
                        dp2[ni][nk] = addPairs(dp2[ni][nk], x);
                    }
                }
                if (i + 1 <= n && k <= m) {
                    dp2[i + 1][k] = addPairs(dp2[i + 1][k], dp2[i][k]);
                }
            }
        }
        System.out.println((int) dp2[n][m].second.val);
        sc.close();
    }

    public static void main(String[] args) {
        processInput();
    }
}

